scripts.build:
node -e 'const fs=require("fs"); const h=fs.readFileSync("index.html","utf8"); fs.copyFileSync("index.html","public/index.html"); fs.writeFileSync("src/index.js", `const HTML = ${JSON.stringify(h)};

export default {
  async fetch(request, env) {
    if (env && env.ASSETS) {
      return env.ASSETS.fetch(request);
    }
    const url = new URL(request.url);
    if (url.pathname === "/assets/logo-club-de-abasto.webp") {
      return Response.redirect("https://clubdeabastoalmayoreo.com.mx/__l5e/assets-v1/5616c1db-0f36-4753-a1e7-1fd51adc2c51/logo-club-de-abasto.webp", 302);
    }
    if (url.pathname === "/assets/tienda.jpg") {
      return Response.redirect("https://clubdeabastoalmayoreo.com.mx/assets/tienda-CdwDXRG9.jpg", 302);
    }
    if (url.pathname === "/assets/favicon.png" || url.pathname === "/favicon.ico") {
      return Response.redirect("https://clubdeabastoalmayoreo.com.mx/favicon.png", 302);
    }
    return new Response(HTML, { headers: { "content-type": "text/html;charset=UTF-8", "cache-control": "public, max-age=600" } });
  }
};
`); console.log("Build completed.");'
